{"query": "PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX kgo: <https://example.org/story-kg/ontology#>

SELECT DISTINCT ?id ?name ?definition ?description
WHERE {
  {
    ?id rdf:type schema:DefinedTerm ;
        schema:name ?name .
    OPTIONAL { ?id schema:description ?description . }
    OPTIONAL { ?id rdfs:comment ?definition . }
    FILTER (CONTAINS(LCASE(?name), "дочитывание") || CONTAINS(LCASE(?description), "дочитывание") || CONTAINS(LCASE(?definition), "дочитывание"))
  }
  UNION
  {
    ?id rdf:type schema:Claim ;
        schema:text ?name .
    FILTER (CONTAINS(LCASE(?name), "дочитывание"))
  }
}"}

